import fs from "node:fs";
import postgres from "/Users/haru/ghq/github.com/harusame-dev/formawork.ai/packages/db/node_modules/postgres/src/index.js";

const env = fs.readFileSync(".vercel/.env.preview.local", "utf8");
const url = env.match(/^DATABASE_URL="?([^"\n]+)/m)[1];
const schema = "formawork_ai_web_crawdworks_13271198";
const sql = postgres(url, { prepare: false, max: 1 });

const out = {};
try {
  out.search_path = (await sql`show search_path`)[0];
  out.vector_ext = await sql`select extname, extnamespace::regnamespace::text as schema from pg_extension where extname='vector'`;
  out.col_type = await sql`
    select udt_schema, udt_name, data_type
    from information_schema.columns
    where table_schema=${schema} and table_name='translation_memories' and column_name='source_embedding'`;
  out.tm_count = (await sql`select count(*)::int from ${sql(schema)}.translation_memories`)[0];
  // 実際に失敗しているクエリを最小再現
