    out.distance_query = { ok: true, rows: r.length };
  } catch (e) {
    out.distance_query = { ok: false, code: e.code, message: e.message };
  }
} catch (e) {
  out.fatal = { code: e.code, message: e.message };
} finally {
  await sql.end();
}
